--
-- Table structure for table `pendaftar_awal`
--

CREATE TABLE `pendaftar_awal` (
  `id` int(11) NOT NULL,
  `id_pendaftar` varchar(50) DEFAULT NULL,
  `nama_ananda` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `no_wa` varchar(20) DEFAULT NULL,
  `bukti_transfer` varchar(255) DEFAULT NULL,
  `is_verified` tinyint(1) DEFAULT 0,
  `tahap` int(1) NOT NULL DEFAULT 0 COMMENT '0=Verifikasi, 1=Pendaftaran, 2=Observasi Sit In, 3=Observasi Klasikal & Wawancara, 4=Selesai',
  `jenjang` varchar(10) NOT NULL,
  `hasil_seleksi` varchar(20) DEFAULT NULL,
  `keterangan_seleksi` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

